{"sql":"WITH wins AS (
 SELECT TeamName, count(*) AS wins FROM results WHERE session='R' AND Position=1 GROUP BY TeamName
),
points AS (
 SELECT TeamName, sum(Points) AS points FROM results WHERE session='R' GROUP BY TeamName
),
combined AS (
 SELECT w.TeamName, w.wins, p.points FROM wins w JOIN points p USING (TeamName)
)
SELECT TeamName, wins, points FROM combined WHERE wins = (SELECT max(wins) FROM combined);
"}

