{"sql":"WITH totals AS (
  SELECT FullName, SUM(Points) AS points
  FROM results
  WHERE session='R' AND season=2024
  GROUP BY FullName
), max_points AS (
  SELECT MAX(points) AS max_points FROM totals
)
SELECT t.FullName, t.points
FROM totals t
JOIN max_points m ON t.points = m.max_points
ORDER BY t.points DESC, t.FullName;
"}

